#!/bin/bash
# Quick Manual Test: Verify Mining-Wallet Integration Works
# Tests: createhdwallet → deriveminingaddress → mine → check balance

set -e

DAEMON="./build/dinerod"
RPC_PORT=20998
DATA_DIR="./data-test-manual"

echo "🧪 Quick Manual Test: Mining-Wallet Integration"
echo "=============================================="

# Cleanup
cleanup() {
    echo ""
    echo "🧹 Cleaning up..."
    pkill -f "dinerod.*$DATA_DIR" || true
    sleep 2
    rm -rf "$DATA_DIR"
}
trap cleanup EXIT

# Start daemon
echo "📡 Starting daemon in regtest mode..."
rm -rf "$DATA_DIR"
mkdir -p "$DATA_DIR"
$DAEMON -datadir="$DATA_DIR" -rpcport=$RPC_PORT -port=20999 -regtest -dev -printtoconsole > "$DATA_DIR/daemon.log" 2>&1 &
DAEMON_PID=$!
sleep 5

# Wait for RPC
echo "⏳ Waiting for RPC server..."
for i in {1..30}; do
    if curl -s -X POST http://127.0.0.1:$RPC_PORT/ \
        --data-binary '{"jsonrpc":"1.0","id":"test","method":"getblockcount","params":[]}' \
        -H 'content-type: text/plain;' > /dev/null 2>&1; then
        echo "✅ Daemon ready"
        break
    fi
    [ $i -eq 30 ] && { echo "❌ Daemon failed to start"; exit 1; }
    sleep 1
done

# Helper for RPC calls
rpc() {
    local method=$1
    local params=$2
    curl -s -X POST http://127.0.0.1:$RPC_PORT/ \
        --data-binary "{\"jsonrpc\":\"1.0\",\"id\":\"test\",\"method\":\"$method\",\"params\":$params}" \
        -H 'content-type: text/plain;'
}

